import os
import sqlite3
from contextlib import closing

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("reservations")

DB_PATH = os.environ.get("RESERVATIONS_DB", "reservations.db")


@mcp.tool()
def reschedule_reservation(reservation_id: int, new_time: str) -> str:
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            res = conn.execute(
                "SELECT id, restaurant_id, party_size, status FROM reservations WHERE id = ?",
                (reservation_id,),
            ).fetchone()
            if res is None:
                return "Reservation {} not found".format(reservation_id)
            if res["status"] not in ("confirmed", "pending"):
                return "Cannot reschedule a reservation with status {}".format(res["status"])

            booked = conn.execute(
                "SELECT COALESCE(SUM(party_size), 0) FROM reservations "
                "WHERE restaurant_id = ? AND reserved_at = ? AND status != 'cancelled' AND id != ?",
                (res["restaurant_id"], new_time, reservation_id),
            ).fetchone()[0]
            cap = conn.execute(
                "SELECT seat_capacity FROM restaurants WHERE id = ?",
                (res["restaurant_id"],),
            ).fetchone()[0]
            if booked + res["party_size"] > cap:
                return "Slot {} is full ({}/{} seats taken)".format(new_time, booked, cap)

            conn.execute(
                "UPDATE reservations SET reserved_at = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                (new_time, reservation_id),
            )
    return "Reservation {} moved to {}".format(reservation_id, new_time)
